function attachEngineForms(){const loc=$('engineLocation');if(loc)loc.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(loc));state.meta.sourceWorkbookName=d.sourceWorkbookName.trim();state.meta.sourceWorkbookPath=d.sourceWorkbookPath.trim();delete state.meta.sourceWorkbook;persist()};const form=$('engineParams');if(form)form.onsubmit=e=>{e.preventDefault();const next=structuredClone(engineModel());for(const [k,v] of new FormData(form))next[k]=k==='strategy'?v:Number(v)/(['annualInterest','cet'].includes(k)?100:1);reconcileEditableParameters(next,engineModel());try{MinhaObraEngine.calculate(next);state.meta.engine.config=next;persist()}catch(err){msg(err.message)}};const rates=$('engineRates');if(rates){rates.querySelectorAll('input').forEach(x=>x.step='any');rates.onsubmit=e=>{e.preventDefault();const next=structuredClone(engineModel()),d=Object.fromEntries(new FormData(rates));next.cdi.forEach(x=>x.annual=Number(d['cdi'+x.year])/100);next.cdbShare=Number(d.cdbShare)/100;next.indicatorNetFactor=Number(d.indicatorNetFactor)/100;try{MinhaObraEngine.calculate(next);state.meta.engine.config=next;engineStamp();state.meta.updated=new Date().toISOString();localStorage.setItem(STORAGE,JSON.stringify(state));dirty=true;scheduleSync();refreshComputedViews()}catch(err){msg(err.message)}}}document.querySelectorAll('.land-paid-form').forEach(f=>f.onsubmit=e=>{e.preventDefault();const n=Number(new FormData(f).get('landPaid'));if(!Number.isFinite(n)||n<0)return msg('Informe um valor pago válido');state.meta.landPaid=n;persist()});form?.querySelectorAll('input').forEach(x=>x.step='any');if(engineModel()?.investmentSourceUpdated&&form?.elements.investments){form.elements.investments.readOnly=true;form.elements.investments.title='Saldo sincronizado do Controle Financeiro';}if(form){form.oninput=()=>liveEngineForm(form,false);form.onchange=()=>liveEngineForm(form,false)}if(rates){rates.oninput=()=>liveEngineForm(rates,true);rates.onchange=()=>liveEngineForm(rates,true)}}
function projections(r,kind){const rows=kind==='sacExcel'?r.sac:r.cash,from=enginePage*40,to=Math.min(rows.length,from+40),cols=kind==='sacExcel'?'ABCDEFGHIJKLMNO':'ABCDEFGHIJ';const headers=kind==='sacExcel'?['Mês','Nº','Saldo inicial','TR','Juros','Amortização','MIP','DFI','Administração','FGHAB (fora de L)','Extra','Parcela','Saldo final','Quitado','Idade','Fase','Liberação prevista']:['Mês','Nº','Reserva inicial','CDB líquido','Rendimento','Salário','Extras','Parcela','Reserva final','Fator líquido IR','Entradas manuais','Saídas manuais'];return '<div class="card"><h2>'+ (kind==='sacExcel'?'Financiamento SAC':'Recursos próprios — fluxo de caixa')+'</h2><div class="actions"><button '+(enginePage===0?'disabled':'')+' onclick="enginePage--;render()">Anterior</button><button '+(to>=rows.length?'disabled':'')+' onclick="enginePage++;render()">Próxima</button></div><p>Meses '+(from+1)+'–'+to+' de '+rows.length+'</p>'+engineTable(headers,rows.slice(from,to).map(x=>(kind==='sacExcel'?[...cols,'phase','release']:[...cols,'manualIn','manualOut']).map(k=>k==='A'||k==='N'||k==='phase'?x[k]:['B','O'].includes(k)?x[k]:['D','J'].includes(k)&&kind==='caixaExcel'||k==='D'&&kind==='sacExcel'?(x[k]*100).toFixed(5)+'%':money(x[k]))))+'</div>'}
function scheduleView(r){return '<div class="card"><h2>Cronograma mensal detalhado</h2><p class="warn">Diferença entre pagamentos e fontes: '+money(r.scheduleTotals.gap)+'. Próprios financiam somente a construtora. Ordem prevista: próprios → FGTS → Caixa. Liberações dependem da aprovação bancária.</p>'+engineTable(['Mês','Etapa','Serviços','Pagamento / contrato (%)','Pago / contrato acumulado (%)','Pagamento','Pago acum.','Caixa prevista','FGTS previsto','Próprios','Diferença fontes','Condição'],r.schedule.map(x=>[x.month,x.name,x.services,(x.payment/r.parameters.B4*100).toFixed(1),(x.paymentTotal/r.parameters.B4*100).toFixed(1),money(x.payment),money(x.paymentTotal),money(x.caixa),money(x.fgts),money(x.own),money(x.sourceGap),x.condition]))+'</div>'}
render=function(){if(!state)return;if(tab==='documentos')tab='contrato';if(['premissasExcel','parametrosExcel','painel'].includes(tab))tab='resumo';const engineTabs=['resumo','premissas','sacExcel','caixaExcel','cronograma'];if(!engineTabs.includes(tab)){originalRender();if(['settings','ajustes'].includes(tab)){$('view').insertAdjacentHTML('beforeend',engineControls()+(engineModel()?engineStatus(engineResult()):''));attachEngineForms()}if(tab==='contrato'){if(engineModel())$('view').insertAdjacentHTML('beforeend',summaryView(engineResult(),'observations'));loadContractReference();}return}ensure();ensureContractDefaults();$('tabs').innerHTML=tabs.map(([k,l])=>'<button class="'+(tab===k?'sel':'')+'" data-k="'+k+'">'+l+'</button>').join('');document.querySelectorAll('#tabs button').forEach(b=>b.onclick=()=>{tab=b.dataset.k;enginePage=0;render()});$('account').textContent=user?'Microsoft: '+user.username:'Microsoft desconectado';syncMicrosoftUi();let body=tab==='resumo'?'<h2>Resumo da obra</h2>':'';try{const r=engineResult();if(tab==='resumo'||tab==='premissas')body+=summaryView(r,tab);else{if(tab==='cronograma')body+=contractorPanel(false,true)+scheduleView(r);else body+=projectionOverview(r,tab)+projections(r,tab);}}catch(e){body+='<div class="card"><p>'+esc(e.message)+'</p></div>'}$('view').innerHTML=body;attachEngineForms();setupExtras();attachStageInputs();attachCharts()};

parseWorkbook=function(buffer){if(!window.XLSX)throw Error('Leitor Excel indisponível');sourceWorkbookBytes=buffer;const book=XLSX.read(buffer,{type:'array',cellDates:true}),cells=MinhaObraWorkbook.cellsFromXlsx(book);const baseline=MinhaObraWorkbook.configFromCells(cells),result=MinhaObraEngine.calculate({...baseline,trCapitalizes:false}),validation=MinhaObraWorkbook.compare(cells,result);if(!validation.passed)throw Error('Conferência reprovada: '+validation.differences.length+' divergências, '+validation.unmapped.length+' fórmulas sem cobertura');state.meta.engine={version:1,config:{...baseline,fgts:77000,premiseFgts:77000},referenceConfig:baseline,validation,importedAt:new Date().toISOString()};engineStamp();localStorage.setItem(STORAGE,JSON.stringify(state));dirty=true;scheduleSync();renderUnlessEditing();if(!document.querySelector('#view input:not([hidden])'))render();msg('Motor validado: '+validation.formulaCount+' fórmulas. FGTS do cenário: R$77.000; principal: R$339.000. Abra a aba desejada para recalcular.')};
async function importEngineFile(ev){try{const f=ev.target.files?.[0];if(f)parseWorkbook(await f.arrayBuffer());render()}catch(e){msg('Importação: '+e.message)}finally{ev.target.value=''}}
async function loadEngineOneDrive(){try{msg('Lendo a planilha privada...');const item=await resolvePrivateWorkbook();const response=await fetch('https://graph.microsoft.com/v1.0/me/drive/items/'+encodeURIComponent(item.id)+'/content',{headers:{Authorization:'Bearer '+await token()}});if(!response.ok)throw Error('Download: HTTP '+response.status);parseWorkbook(await response.arrayBuffer());render()}catch(e){msg('OneDrive: '+e.message)}}
function exportEngineValidation(){if(!state.meta.engine)return msg('Importe a planilha primeiro');blob(JSON.stringify({reference:state.meta.engine.validation,current:engineResult(),limitations:engineResult().warnings},null,2),'minha-obra-conferencia-'+today()+'.json','application/json')}
// Engine reference/config is private. Existing cost overrides survive migration.
var originalCostDelete=deleteOwnCost,originalCostRename=renameOwnCost;
deleteOwnCost=function(i){const x=ownCostRows()[i];if(x?.record)return remove('gastos',x.id);return originalCostDelete(i)};
renameOwnCost=function(i){const x=ownCostRows()[i];if(x?.record)return attachForm('gastos',x.id);return originalCostRename(i)};

function premiseView(r){const c=engineModel();return '<div class="card"><h2>Premissas — quadros e fontes da origem</h2>'+engineTable(['Premissa / etapa','Valor / percentual','Fonte / valor','Divisão','Mês','Serviços'],(c.premiseRows||[]).filter(row=>row.some(x=>x.label!==null)).map(row=>row.map(x=>Object.hasOwn(r.premises,x.cell)?typeof r.premises[x.cell]==='number'?money(r.premises[x.cell]):r.premises[x.cell]:x.cell==='B9'?money(339000):x.cell==='B10'?money(c.fgts):x.label??'')))+'</div>'}
function indicatorView(r){return '<div class="card"><h2>Parâmetros e indicadores calculados</h2>'+engineTable(['Indicador','Valor calculado'],Object.entries(r.parameters).map(([k,v])=>[engineModel().parameterLabels?.[k]||k,typeof v==='number'?v.toLocaleString('pt-BR',{maximumFractionDigits:6}):v??'Indisponível']))+'</div>'}

async function resolvePrivateWorkbook(){let item=null;if(state.meta.sourceWorkbookPath){item=await graph('/me/drive/root:/'+state.meta.sourceWorkbookPath.split('/').filter(Boolean).map(encodeURIComponent).join('/'))}else if(state.meta.sourceWorkbook?.id){item=await graph('/me/drive/items/'+encodeURIComponent(state.meta.sourceWorkbook.id))}if(!item){const name=state.meta.sourceWorkbookName||'financiamento construção casa.xlsx';const result=await graph("/me/drive/root/search(q='"+encodeURIComponent(name)+"')");const files=(result?.value||[]).filter(x=>x.name===name&&x.file);if(files.length!==1)throw Error(files.length?'Há arquivos com o mesmo nome. Informe o caminho em Arquivo no OneDrive.':'Planilha não encontrada. Informe o nome em Arquivo no OneDrive.');item=files[0]}state.meta.sourceWorkbook={id:item.id,name:item.name,parentReference:item.parentReference};return item}

function summaryView(r,mode='resumo'){
 const c=engineModel(),p=r.parameters,q=state.meta.engine.validation;
 const indicators=[['Quitação prevista',r.payoff||'Não quitado no horizonte'],['Prazo até quitação',p.N6===null?'Indisponível':p.N6+' meses ('+p.N7.toFixed(1)+' anos)'],['Projeto: terreno + construção',money(p.B3)],['Construção por m²',money(p.B6)],['Projeto por m²',money(p.B7)],['Recursos próprios na construção',money(r.premises.B11)],['Complemento à vista com terreno',money(p.H5)],['Despesas próprias previstas',money(r.extras)],['Recursos próprios necessários',money(p.K3)],['Reserva inicial',money(p.K6)],['A pagar na primeira etapa',money(Math.max(0,r.premises.B6))],['CET anual informado',(p.H8*100).toFixed(2)+'%'],['Juros totais',money(p.N10)],['Total do financiamento',money(p.N11)],['Custos do financiamento além do principal',money(p.H14)],['Desembolso total com recursos próprios',money(p.K7)],['Reserva mínima — cenário atual',money(p.N8)],['Mês da reserva mínima — cenário atual',p.N4],['Primeiro mês com reserva negativa',p.P5||'Nenhum'],['Reserva na quitação',money(p.N9)],['Idade no indicador da origem',p.N5],['Juros mensais', (p.H7*100).toFixed(4)+'%'],['CDI de referência do indicador',(p.K8*100).toFixed(2)+'%'],['Rendimento líquido mensal do indicador',(p.K9*100).toFixed(4)+'%'],['Rendimento líquido anual do indicador',(p.N15*100).toFixed(2)+'%'],['Custos / total do financiamento',(p.N12*100).toFixed(2)+'%'],['Estratégia indicada pela comparação de taxas',p.N16],['Indicador auxiliar: cenário 500',money(p.N13)],['Reserva adicional do indicador',money(p.N17)],['Indicador auxiliar: cenário 300',money(p.N18)]];
 const stages=(c.stages||[]).map((x,i)=>{const row=c.premiseRows?.[15+i];return [x.name,(x.share*100).toFixed(1)+'%',money(i===0?c.firstStage:x.amount),...([3,4,5].map(j=>row?.[j]?.label||''))]});
 const notes=(c.premiseRows||[]).filter((row,i)=>((i>=3&&i<=12)||(i>=26&&i<=32))&&row[2]?.label).map(row=>[row[0]?.label||'',row[2].label]);
 const sourceRows=(c.premiseRows||[]).slice(35).filter(row=>row.some(x=>x.label!==null)).map(row=>[row[0]?.label||'',row[1]?.label||'']);
 const html='<div class="card" id="summaryProjection"><h2>Dívida, reserva e despesa</h2>'+interactiveChart(r.sac.map((x,i)=>[x.A,x.M,r.cash[i].I,x.L+x.K+r.expenseTimeline[i].contractor+r.expenseTimeline[i].ownExpenses]),['Saldo do financiamento','Recursos próprios','Despesa total no mês'],false)+'</div>'+allocationView(r,'chart')+expenseView(r)+'<div class="card" id="summaryAnnual">'+annualPositionView(r)+'</div>'+allocationView(r,'tables')+parameterForm()+monthlyExtras()+'<div class="card" id="summaryStages"><h2>Etapas contratuais</h2>'+stageInputs(c)+'</div><details class="card"><summary>Observações e fontes da planilha</summary>'+engineTable(['Informação','Observação'],notes)+engineTable(['Documento / fonte','Detalhe'],sourceRows)+'</details>';const split=html.indexOf('<div class="card"><h2>Dados da obra e do financiamento</h2>');const observations=html.indexOf('<details class="card"><summary>Observações e fontes da planilha</summary>');return mode==='observations'?html.slice(observations):mode==='premissas'?html.slice(split,observations):summaryOverview(r,indicators.filter(x=>!/Reserva|reserva|Quitação|quitação|Idade no indicador|Juros totais|Total do financiamento|Custos do financiamento|Desembolso total/.test(x[0])))+fundingBalanceView(r)+houseExpenseView();
}

function interactiveChart(data,labels,percent){
 const width=780,height=290,pad=58,plotBottom=244;const values=data.flatMap(x=>x.slice(1)).filter(Number.isFinite),top=Math.max(percent?.001:1,...values),bottom=Math.min(0,...values),sx=i=>pad+i*(width-pad-20)/Math.max(1,data.length-1),sy=v=>plotBottom-(v-bottom)/(top-bottom||1)*(plotBottom-25);const fmt=v=>percent?(v*100).toFixed(3)+'%':money(v);const path=j=>data.map((x,i)=>(i?'L':'M')+sx(i).toFixed(1)+','+sy(x[j]).toFixed(1)).join(' ');const ticks=[...new Set(Array.from({length:7},(_,i)=>Math.round(i*(data.length-1)/6)))];
 return '<div class="interactive-chart" data-chart="'+esc(JSON.stringify({data,labels,percent}))+'"><svg role="img" aria-label="'+esc(labels.join(' e '))+' por mês" viewBox="0 0 780 290" style="width:100%;display:block;touch-action:pan-y">'+labels.map((label,i)=>'<path d="'+path(i+1)+'" fill="none" stroke="'+['#66aaff','#61dfb1','#ffbf69'][i]+'" stroke-width="3"/>').join('')+'<text x="8" y="18" fill="currentColor" font-size="12">'+esc(fmt(top))+'</text><text x="8" y="244" fill="currentColor" font-size="12">'+esc(fmt(bottom))+'</text>'+ticks.map(i=>'<text x="'+sx(i)+'" y="270" text-anchor="middle" fill="currentColor" font-size="12">'+data[i][0].slice(5,7)+'/'+data[i][0].slice(2,4)+'</text>').join('')+'<line class="chart-cursor" x1="58" x2="58" y1="25" y2="244" stroke="currentColor" stroke-dasharray="4 4"/></svg><div>'+labels.map((label,i)=>['🔵','🟢','🟠'][i]+' '+esc(label)).join(' · ')+'</div><output class="chart-values" style="display:block;margin:12px 0" aria-live="polite"></output><label>Selecionar mês<input class="chart-month" type="range" min="0" max="'+(data.length-1)+'" value="0" style="width:100%"></label></div>';
}
function attachCharts(){document.querySelectorAll('.interactive-chart').forEach(el=>{const {data,labels,percent}=JSON.parse(el.dataset.chart),svg=el.querySelector('svg'),range=el.querySelector('input');const show=i=>{i=Math.max(0,Math.min(data.length-1,i));range.value=i;const row=data[i],fmt=v=>percent?(v*100).toFixed(4)+'% ao mês':money(v);el.querySelector('output').textContent=row[0].slice(5,7)+'/'+row[0].slice(0,4)+' · '+labels.map((label,j)=>label+': '+fmt(row[j+1])).join(' · ');const x=58+i*702/Math.max(1,data.length-1),line=el.querySelector('.chart-cursor');line.setAttribute('x1',x);line.setAttribute('x2',x)};svg.onpointermove=e=>{const bounds=svg.getBoundingClientRect();show(Math.round(((e.clientX-bounds.left)/bounds.width*780-58)/702*(data.length-1)))};range.oninput=()=>show(Number(range.value));show(Number(range.value)||0)})}
function allocationView(r,mode='all'){const rows=r.allocation;const changes=rows.filter((x,i)=>i===0||x.destination!==rows[i-1].destination);const label=x=>x==='amortizacao'?'Abater financiamento':'Aumentar investimento';const html= '<div class="card" id="summaryAllocation"><h2>Investimento × financiamento</h2><p class="warn">Durante a obra, extras ficam investidos para manter disponibilidade. Isso é uma regra provisória de liquidez; não significa que o rendimento supere o custo da dívida. Após a obra, aplica-se a comparação de taxas.</p><p>Os aportes extras seguem automaticamente a maior vantagem mensal estimada. Em empate, abatem a dívida. Após a quitação, vão para o investimento.</p><p class="fine">Comparamos CDB líquido de IR com juros + TR + MIP proporcional. DFI e administração fixos não diminuem com uma amortização parcial. A regra usa as taxas projetadas de cada mês; não garante o melhor resultado de todo o período.</p>'+interactiveChart(rows.map(x=>[x.month,x.financeRate,x.investmentRate]),['Custo evitável do financiamento','Rendimento líquido do investimento'],true)+'<h3>Períodos e avisos de mudança</h3>'+engineTable(['De','Até','Destino dos extras'],changes.map((x,i)=>[x.month,i+1<changes.length?rows[rows.indexOf(changes[i+1])-1].month:rows.at(-1).month,label(x.destination)]))+'<details><summary>Ver distribuição mês a mês</summary><p class="fine">'+(rows.some(x=>x.contributionTotal>0)?'Aportes previstos do salário, PLR, FGTS e programações. A tabela mostra apenas meses com valores destinados.':'Nenhum aporte previsto nesse cenário. Confira os parâmetros e as programações.')+'</p>'+engineTable(['Mês','Fase','Origem','Total dos aportes','Abate da dívida','Para investimento'],rows.filter(x=>x.contributionTotal>0).map(x=>[x.month,x.phase,x.sources.join(', '),money(x.contributionTotal),money(x.totalToDebt),money(x.totalToInvestment)]))+'</details><p class="fine">Salário e amortizações escolhidas explicitamente mantêm seu destino. PLR segue o parâmetro próprio; FGTS segue sua regra de amortização. O aplicativo apenas simula a distribuição, sem movimentar dinheiro no banco.</p></div>';const split=html.indexOf('<h3>Períodos e avisos');if(mode==='chart')return html.slice(0,split)+'</div>';if(mode==='tables')return '<div class="card" id="summaryPeriods">'+html.slice(split);return html}

function annualPositionView(r){const years=new Map();r.sac.forEach((s,i)=>{const year=s.A.slice(0,4),c=r.cash[i],d=r.expenseTimeline[i],a=r.allocation[i];if(!years.has(year))years.set(year,{year,last:s.A,opening:c.C,closing:0,salary:0,plr:0,fgts:0,contributions:0,earnings:0,withdrawals:0,manualNet:0,installments:0,amortizations:0,debt:0,contractor:0,other:0,expenses:0,investmentPayment:0,salaryPayment:0,unfunded:0});const x=years.get(year);x.last=s.A;x.closing=c.I;x.salary+=d.salary;x.plr+=d.plr;x.fgts+=d.fgts;x.contributions+=a.totalToInvestment;x.earnings+=c.E;x.withdrawals+=s.L+c.deferredPayment;x.manualNet+=c.manualIn-c.manualOut;x.investmentPayment+=c.paymentFromInvestment||0;x.salaryPayment+=c.paymentFromSalary||0;x.unfunded+=c.unfunded||0;x.installments+=s.L;x.amortizations+=s.K;x.debt=s.M;x.contractor+=d.contractor;x.other+=d.ownExpenses;x.expenses+=s.L+s.K+d.contractor+d.ownExpenses;});return '<h3>Posição anual do investimento, financiamento e despesas</h3><p class="fine">Salário, PLR e FGTS são fontes identificadas; não são somados como despesas. O investimento fecha por saldo inicial + aportes ao investimento + rendimentos + movimentos manuais líquidos − retiradas. Aportes à dívida já estão nas amortizações. Construtora e outros seguem o cronograma; valores já provisionados não são retirados novamente.</p>'+engineTable(['Ano','Posição em','Investimento inicial','Salário','PLR','FGTS aplicado','Aportes ao investimento','Rendimentos líquidos','Retiradas do investimento','Movimentos manuais líquidos','Saldo do investimento','Parcelas Caixa','Parcelas com investimento','Parcelas com salário','Pagamentos sem cobertura','Amortizações Caixa','Saldo devedor','Construtora','Outros: documentos, móveis e eletros','Despesas e pagamentos no ano'],[...years.values()].map(x=>[x.year,x.last,...['opening','salary','plr','fgts','contributions','earnings','withdrawals','manualNet','closing','installments','investmentPayment','salaryPayment','unfunded','amortizations','debt','contractor','other','expenses'].map(k=>money(x[k]))]))+'<p class="fine">Fontes e destinos são mostrados para análise, sem um total que some entradas e saídas. FGTS é parte das amortizações, não valor adicional a elas. Despesas e pagamentos incluem repasses à construtora e devolução do crédito à Caixa; são desembolsos brutos, não custo líquido do imóvel. Saldos correspondem ao último mês do ano, incluindo anos parciais.</p>'}
function stagePaymentRows(stages,payments){return linkedStageRows().map((x,i)=>'<tr><td>'+esc(x.nome)+'</td><td>'+esc(x.mesInicio||'A confirmar')+'</td><td>'+esc(x.mesFim||'A confirmar')+'</td><td>'+money(x.valor)+'</td><td>'+money(stagePaidAmount(x,i,payments))+'</td></tr>').join('')}

function houseExpenseView(){const v=expenseSnapshot(),c=engineModel(),land=v.land,landPaid=v.landPaid,stages=v.stages,payments=v.payments,materials=v.materials,own=v.own,stagePlan=v.contract,stagePaid=v.paid,matPlan=v.difference,matPaid=v.materialPaid,ownPlan=v.ownPlan,ownPaid=v.ownPaid;const tr=(name,plan,paid,expand='')=>'<tr><td>'+(expand?'<details><summary>'+esc(name)+'</summary>'+expand+'</details>':esc(name))+'</td><td>'+money(plan)+'</td><td>'+money(paid)+'</td><td>'+money(Math.max(0,plan-paid))+'</td></tr>';const itemTable=(items,labels)=>engineTable(['Descrição','Previsto','Pago','A pagar'],items.map(x=>[x[labels[0]],money(Number(x[labels[1]]||0)),money(Number(x[labels[2]]||0)),money(Math.max(0,Number(x[labels[1]]||0)-Number(x[labels[2]]||0)))]));const stagesTable=engineTable(['Etapa','Mês início','Mês fim','Previsto','Pago','A pagar'],stages.map((x,i)=>{const paid=stagePaidAmount(x,i,payments);return [x.nome,x.mesInicio||'A confirmar',x.mesFim||'A confirmar',money(x.valor),money(paid),money(Math.max(0,Number(x.valor||0)-paid))]}));const contractor='<details><summary>Etapas</summary>'+stagesTable+'</details><details><summary>Diferenças de materiais</summary>'+itemTable(materials,['nome','difference','valorPago'])+'</details>';const ownRows=own.map(x=>({name:x.name,planned:x.planned,paid:x.paid}));const ownDetails=itemTable(ownRows,['name','planned','paid']);const expenseTable='<div class="sheet-scroll"><table><thead><tr>'+['Descrição','Previsto','Pago','A pagar'].map(x=>'<th>'+esc(x)+'</th>').join('')+'</tr></thead><tbody>'+[tr('Compra Terreno',land,landPaid,'<form class="land-paid-form"><label>Valor pago pela compra (R$)<input name="landPaid" type="number" min="0" step="0.01" value="'+landPaid+'"></label><button>Salvar valor pago</button></form>'),tr('Construtora',stagePlan+matPlan,stagePaid+matPaid,contractor),tr('Despesas próprias',ownPlan,ownPaid,ownDetails)].join('')+'</tbody><tfoot><tr style="font-weight:700;background:#294767"><td>Total</td><td>'+money(land+stagePlan+matPlan+ownPlan)+'</td><td>'+money(landPaid+stagePaid+matPaid+ownPaid)+'</td><td>'+money(Math.max(0,land-landPaid)+Math.max(0,stagePlan+matPlan-stagePaid-matPaid)+Math.max(0,ownPlan-ownPaid))+'</td></tr></tfoot></table></div>';return '<div class="card" id="summaryHouseExpenses"><h2>Despesas da Casa nova</h2><p class="fine">“A pagar” é o previsto menos o pago, limitado a zero. As diferenças de materiais mostram somente a variação sobre o preço original.</p>'+expenseTable+'</div>'}

function consolidatedValues(){const v=expenseSnapshot();return {'Previsão consolidada':v.land+v.contract+v.difference+v.ownPlan,'Pago consolidado':v.landPaid+v.paid+v.materialPaid+v.ownPaid,'Construtora prevista':v.contract+v.difference,'Construtora paga':v.paid+v.materialPaid,'Recursos próprios previstos':v.ownPlan,'Recursos próprios pagos':v.ownPaid,'Diferença materiais':v.difference,'Pago compra terreno':v.landPaid}}
function refreshComputedViews(){const values=consolidatedValues();const planned=$('ownTotalPlanned'),paid=$('ownTotalPaid'),footer=$('ownCostFooter');if(planned)planned.textContent=money(values['Recursos próprios previstos']);if(paid)paid.textContent=money(values['Recursos próprios pagos']);if(footer)footer.textContent='Total previsto: '+money(values['Recursos próprios previstos'])+' · Total pago: '+money(values['Recursos próprios pagos']);document.querySelectorAll('[data-consolidated]').forEach(el=>el.textContent=money(values[el.dataset.consolidated]));if(!['resumo','premissas'].includes(tab)||!engineModel())return;try{const fresh=document.createElement('div');fresh.innerHTML=summaryView(engineResult(),tab);for(const id of ['summaryOverview','summaryReferenceReserve','summaryFunding','summaryHouseExpenses','summaryIndicators','summaryStages','summaryProjection','summaryExpenses','summaryAllocation','summaryAnnual','summaryPeriods']){const old=$(id),next=fresh.querySelector('#'+id);if(old&&next){if(id==='summaryStages'&&tab==='premissas')continue;const scrollPositions=[...old.querySelectorAll('.sheet-scroll')].map(x=>({top:x.scrollTop,left:x.scrollLeft}));const selected=[...old.querySelectorAll('.chart-month')].map(x=>x.value),opened=[...old.querySelectorAll('details')].map(x=>x.open);old.replaceWith(next);next.querySelectorAll('.sheet-scroll').forEach((x,i)=>{x.scrollTop=scrollPositions[i]?.top||0;x.scrollLeft=scrollPositions[i]?.left||0});next.querySelectorAll('.chart-month').forEach((x,i)=>x.value=selected[i]||0);next.querySelectorAll('details').forEach((x,i)=>x.open=opened[i]||false)}}refreshLinkedStageFields();refreshLinkedParameterFields();attachEngineForms();attachStageInputs();attachCharts()}catch(e){msg(e.message)}}
function liveEngineForm(form,isRates){const data=Object.fromEntries(new FormData(form));if(Object.values(data).some(v=>v===''))return;const next=structuredClone(engineModel());if(isRates){next.cdi.forEach(x=>x.annual=Number(data['cdi'+x.year])/100);next.cdbShare=Number(data.cdbShare)/100;next.indicatorNetFactor=Number(data.indicatorNetFactor)/100}else{for(const [k,v] of Object.entries(data))next[k]=k==='strategy'?v:Number(v)/(['annualInterest','cet'].includes(k)?100:1);reconcileEditableParameters(next,engineModel())}try{MinhaObraEngine.calculate(next);state.meta.engine.config=next;engineStamp();state.meta.updated=new Date().toISOString();localStorage.setItem(STORAGE,JSON.stringify(state));dirty=true;scheduleSync();refreshComputedViews()}catch(e){msg(e.message)}}

function expenseView(r){return '<div class="card" id="summaryExpenses"><h2>Despesas mensais por tipo</h2><p class="fine">Móveis e eletros ainda não pagos em oito parcelas, após a conclusão estimada. Parcelas sem juros presumidos. Outros recursos próprios são provisionados no início; construtora segue o cronograma.</p>'+interactiveChart(r.expenseTimeline.map((x,i)=>[x.month,r.sac[i].L+r.sac[i].K,x.contractor,x.ownExpenses]),['Parcelas e amortizações Caixa','Parcelas da construtora','Outras despesas próprias'],false)+'</div>'}

function syncMicrosoftUi(){const connected=!!user,button=$('headerLogin');if(button){button.hidden=connected;button.classList.toggle('hidden',connected);button.style.setProperty('display',connected?'none':'','important')}document.querySelectorAll('button[onclick="login()"]').forEach(el=>{el.hidden=connected;el.classList.toggle('hidden',connected)});document.querySelectorAll('button[onclick="logout()"]').forEach(el=>el.hidden=!connected);const account=$('account');if(account)account.textContent=connected?'Microsoft: '+user.username:'Microsoft desconectado'}

var contractReferenceLoading=false;async function loadContractReference(){if(!user||contractReferenceLoading||state.meta.contractInfo?.points?.length)return;contractReferenceLoading=true;try{const name='Minha Obra - referencias contratuais.json',found=await graph("/me/drive/root/search(q='"+encodeURIComponent(name)+"')"),file=found.value?.find(x=>x.name===name);if(!file){msg('Arquivo privado de referências contratuais não encontrado no OneDrive.');return}const info=await graph('/me/drive/items/'+encodeURIComponent(file.id)+'/content');if(!Array.isArray(info.points)||!Array.isArray(info.docs))throw Error('Referências inválidas');state.meta.contractInfo=info;engineStamp();state.meta.updated=new Date().toISOString();localStorage.setItem(STORAGE,JSON.stringify(state));dirty=true;scheduleSync();if(tab==='contrato')render()}catch(e){msg('Referências contratuais: '+e.message)}finally{contractReferenceLoading=false}}

var sourceWorkbookBytes=null;async function exportAllWorkbook(){try{let bytes=sourceWorkbookBytes;if(!bytes){const item=await resolvePrivateWorkbook(),response=await fetch('https://graph.microsoft.com/v1.0/me/drive/items/'+encodeURIComponent(item.id)+'/content',{headers:{Authorization:'Bearer '+await token()}});if(!response.ok)throw Error('Download: HTTP '+response.status);bytes=await response.arrayBuffer()}blob(bytes,state.meta.sourceWorkbookName||'financiamento construção casa.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');msg('Cópia do arquivo completo exportada, com todas as abas e fórmulas da origem.')}catch(e){msg('Exportação: '+e.message)}}

function summaryOverview(r,indicators=[]){const c=engineModel();return '<div class="card" id="summaryOverview"><h2>Informações Gerais</h2>'+engineTable(['Rúbrica','Valor'],[['Financiamento inicial',money(c.principal)],['Compra do terreno',money(c.landPurchase??c.land)],['FGTS inicial',money(c.fgts)],['Investimentos atuais',money(c.investments)],['Venda da casa (histórico; não somado ao saldo)',money(c.sale)],...indicators.filter(x=>!['Quitação prevista','Reserva inicial'].includes(x[0]))])+'</div>'}
function projectionOverview(r,kind){const c=engineModel();return '<div class="card"><h2>'+ (kind==='caixaExcel'?'Investimento — posição inicial':'Financiamento — posição inicial')+'</h2>'+engineTable(['Informação','Valor'],kind==='caixaExcel'?[['Investimentos atuais',money(c.investments)],['Venda líquida disponível',money(c.sale)],['Reserva inicial após provisões',money(r.parameters.K6)]]:[['Financiamento inicial',money(c.principal)],['FGTS inicial',money(c.fgts)],['Quitação prevista',r.payoff||'Não quitado no horizonte']])+'</div>'}

function stageInputs(c){const labels=['Etapa','Percentual','Valor','Divisão','Mês início','Mês fim','Serviços'];return engineTable(['Etapa','Percentual (%)','Valor (R$)','Divisão','Mês início','Mês fim','Serviços'],(c.stages||[]).map((x,i)=>{const dates=stageDates(x,i,c);return [x.name,x.share*100,i===0?c.firstStage:x.amount,c.premiseRows?.[15+i]?.[3]?.label||'',dates.start,dates.end,c.premiseRows?.[15+i]?.[5]?.label||''].map((value,j)=>{const month=j===4||j===5,automatic=j===4&&i>0,input='<input aria-label="'+esc(labels[j]+' '+(i+1))+'" data-stage="'+i+'" data-column="'+j+'" type="'+([1,2].includes(j)?'number':month?'month':'text')+'" step="any" '+(automatic?'readonly aria-readonly="true" title="Automático: mês seguinte ao fim da etapa anterior" ':'')+'value="'+esc(value)+'">';if(automatic)return '<div>'+input+'<small>Automático</small></div>';return month?'<div style="display:flex;align-items:center;gap:6px;min-width:235px">'+input+'<button type="button" style="flex-shrink:0;padding:9px" aria-label="'+esc('Escolher '+labels[j].toLowerCase()+' da etapa '+(i+1))+'" title="Escolher mês e ano" onclick="pickStageMonth(this)">📅</button></div>':input})}),true)}
function pickStageMonth(button){const input=button.parentElement.querySelector('input');try{if(typeof input.showPicker==='function'){input.showPicker();return}}catch(e){}const value=input.value||new Date().toISOString().slice(0,7),parts=value.split('-'),months=['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];openRecordDialog('Escolher mês e ano','<form id="stageMonthPicker"><div class="grid"><label>Mês<select name="month">'+months.map((name,i)=>'<option value="'+String(i+1).padStart(2,'0')+'" '+(Number(parts[1])===i+1?'selected':'')+'>'+name+'</option>').join('')+'</select></label><label>Ano<input name="year" type="number" min="1900" max="9999" required value="'+esc(parts[0])+'"></label></div><div class="actions"><button type="submit">Aplicar</button><button type="button" class="secondary" onclick="closeRecordDialog()">Cancelar</button></div></form>');$('stageMonthPicker').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target),year=Number(data.get('year'));if(!Number.isInteger(year)||year<1900||year>9999)return;input.value=String(year).padStart(4,'0')+'-'+data.get('month');closeRecordDialog();input.dispatchEvent(new Event('change',{bubbles:true}))}}

function findStageRecord(x,i){const records=list('etapas'),id=x.recordId||x.id;if(id){const found=records.find(y=>y.id===id);if(found)return found}const number=String(x.name||'').match(/^(\d+)/)?.[1]||String(i+1);return records.find(y=>String(y.nome||'').match(/^(\d+)/)?.[1]===number)||records.find(y=>y.nome===x.name)}
function stageRawDates(x,i,c){const rec=findStageRecord(x,i);if(x.startMonth!==undefined||x.endMonth!==undefined)return {start:x.startMonth??rec?.mesInicio??'',end:x.endMonth??rec?.mesFim??''};if(rec?.mesInicio||rec?.mesFim)return {start:rec.mesInicio||'',end:rec.mesFim||''};const row=c.premiseRows?.[15+i],months=[...(String(row?.[4]?.label||'').matchAll(/M(\d+)/g))].map(m=>Number(m[1])-1),first=c.dates?.[0];const shift=n=>{if(!first)return '';const [y,m]=first.slice(0,7).split('-').map(Number);return new Date(Date.UTC(y,m-1+n,1)).toISOString().slice(0,7)};return {start:months.length?shift(Math.min(...months)):'',end:months.length?shift(Math.max(...months)):''}}

function stageDates(x,i,c){const raw=stageRawDates(x,i,c);if(i===0)return raw;const previous=stageDates(c.stages[i-1],i-1,c),start=previous.end?monthString(monthIndex(previous.end)+1):'';return {start,end:raw.end&&start&&raw.end<start?start:raw.end}}
function applyStageCalendar(c,save=false){(c.stages||[]).forEach((stage,i)=>{const dates=stageDates(stage,i,c);stage.startMonth=dates.start;stage.endMonth=dates.end;if(save){const rec=stageRecord(stage,i);rec.mesInicio=dates.start;rec.mesFim=dates.end;rec.updated=new Date().toISOString()}const from=monthIndex(dates.start),to=monthIndex(dates.end);if(!Number.isFinite(from)||!Number.isFinite(to))return;const rows=(c.schedule||[]).filter(z=>new RegExp('^\\s*'+(i+1)+'\\s*(?:a|ª|º|o)?\\s*etapa','i').test(z.name||''));rows.forEach((z,k)=>z.month=monthString(from+(rows.length<2?0:Math.round(k*(to-from)/(rows.length-1)))))});if(save&&c.stages?.at(-1)?.endMonth){const months=monthIndex(c.stages.at(-1).endMonth)-monthIndex(c.dates[0])+1;if(months>=0&&months<c.term)c.constructionMonths=months}return c}
function refreshStageDateFields(c){document.querySelectorAll('[data-stage][data-column="4"],[data-stage][data-column="5"]').forEach(el=>{const i=Number(el.dataset.stage),dates=stageDates(c.stages[i],i,c);el.value=Number(el.dataset.column)===4?dates.start:dates.end})}

function attachStageInputs(){document.querySelectorAll('[data-stage]').forEach(el=>el.onchange=()=>{const i=Number(el.dataset.stage),j=Number(el.dataset.column),c=structuredClone(engineModel()),s=c.stages[i],value=[1,2].includes(j)?Number(el.value):el.value;if(j===4&&i>0)return;if([1,2].includes(j)&&(!el.value||!Number.isFinite(value)||value<0))return msg('Informe um valor válido');if(j===0){const identity=stageRecord(s,i);s.recordId=identity.id;s.name=value}if(j===1){s.share=value/100;s.amount=c.construction*s.share}if(j===2){s.amount=value;if(i===0)c.firstStage=value}if(j===3||j===6){const row=j===3?3:5;c.premiseRows??=[];c.premiseRows[15+i]??=[];c.premiseRows[15+i][row]??={};c.premiseRows[15+i][row].label=value}if(j===0||j===2){const rec=stageRecord(s,i);rec.nome=s.name;rec.valor=i===0?c.firstStage:s.amount;rec.updated=new Date().toISOString()}if(j===4||j===5){const current=stageDates(s,i,c),start=j===4?value:current.start,end=j===5?value:(j===4&&current.end&&value>current.end?value:current.end);if(start&&end&&start>end){el.value=current[j===4?'start':'end'];return msg('O mês inicial não pode ser posterior ao mês final')}s.startMonth=start;s.endMonth=end;const rec=stageRecord(s,i);rec.mesInicio=start;rec.mesFim=end;rec.updated=new Date().toISOString();const from=monthIndex(start),to=monthIndex(end);if(Number.isFinite(from)&&Number.isFinite(to)){const num=String(i+1),rows=c.schedule.filter(z=>new RegExp('^\\s*'+num+'\\s*(?:a|ª|º|o)?\\s*etapa','i').test(z.name||''));rows.forEach((z,k)=>{const ix=rows.length<2?0:Math.round(k*(to-from)/(rows.length-1));z.month=monthString(from+ix)})}}try{if(j===1||j===2){c.construction=c.stages.reduce((a,x)=>a+Number(x.amount||0),0);c.stages.forEach(x=>x.share=c.construction?x.amount/c.construction:0);c.firstStage=c.stages[0]?.amount??c.firstStage}applyStageCalendar(c,true);MinhaObraEngine.calculate(c);state.meta.engine.config=c;refreshStageDateFields(c);engineStamp();state.meta.updated=new Date().toISOString();localStorage.setItem(STORAGE,JSON.stringify(state));dirty=true;scheduleSync();refreshComputedViews()}catch(e){msg(e.message)}})}
function stageRecord(s,i){state.items.etapas??=[];let rec=findStageRecord(s,i);if(!rec){rec={id:uuid(),nome:s.name,valor:i===0?engineModel().firstStage:s.amount,progresso:0,status:'Planejada'};state.items.etapas.push(rec)}if(rec.id)s.recordId=rec.id;return rec}
function monthIndex(s){if(!/^\d{4}-\d{2}$/.test(String(s||'')))return NaN;const [y,m]=s.split('-').map(Number);return y*12+m-1}
function monthString(i){return String(Math.floor(i/12)).padStart(4,'0')+'-'+String(i%12+1).padStart(2,'0')}

function refreshLinkedStageFields(){const c=engineModel();if(!c)return;document.querySelectorAll('[data-stage][data-column]').forEach(el=>{if(el===document.activeElement&&!el.readOnly)return;const i=Number(el.dataset.stage),j=Number(el.dataset.column),x=c.stages[i];if(!x)return;const dates=stageDates(x,i,c),row=c.premiseRows?.[15+i];el.value=[x.name,x.share*100,i===0?c.firstStage:x.amount,row?.[3]?.label||'',dates.start,dates.end,row?.[5]?.label||''][j]??''})}

function refreshLinkedParameterFields(){const c=engineModel();if(!c)return;document.querySelectorAll('#engineParams input').forEach(el=>{if(el===document.activeElement)return;const value=el.name==='landPurchase'?c.landPurchase??c.land:c[el.name];if(value!==undefined)el.value=['annualInterest','cet'].includes(el.name)?Number((value*100).toFixed(6)):value})}

function fundingBalanceView(r){const f=r.funding;if(!f)return '';return '<div class="card" id="summaryFunding"><h2>Investimento disponível e despesas a pagar</h2><p class="fine">Somente Sofisa e Investimento Itaú entram no saldo atual. A venda da casa é histórica e não é somada novamente. O saldo informado já desconta os pagamentos realizados. Próprios para a construtora = custo total da construtora − financiamento Caixa − FGTS. As parcelas usam primeiro o investimento; o salário automático cobre apenas a falta, respeitando o aporte mensal disponível.</p>'+(state.meta.financialBridgeError?'<p class="warn">Saldos: '+esc(state.meta.financialBridgeError)+'</p>':'')+engineTable(['Cálculo','Valor'],[['Custo total para a construtora',money(r.parameters.B4)],['− Financiamento Caixa',money(r.parameters.H3)],['− FGTS inicial',money(r.parameters.H4)],['= Recursos próprios totais para a construtora',money(f.ownConstructor)],['− Recursos próprios já pagos à construtora',money(f.constructorAlreadyPaid)],['= Recursos próprios ainda necessários para a construtora',money(f.ownConstructorRemaining)],['Sofisa — saldo atual',cBankBalance('sofisa')],['Investimento Itaú — saldo atual',cBankBalance('itau')],['Total dos investimentos disponíveis',money(f.capital)],['− Próprios ainda necessários para a construtora',money(f.ownConstructorRemaining)],['= Saldo após reservar o pagamento à construtora',money(f.afterConstructor)],['− Terreno ainda a pagar',money(f.landRemaining)],['− Outras despesas próprias ainda a pagar',money(f.otherRemaining)],['= Saldo livre após todas as despesas previstas',money(f.afterAll)],['Móveis e eletros a pagar em 8 parcelas após a obra',money(f.deferred)],['Saldo que permanece investido para calcular rendimentos',money(f.startingReserve)],['Falta de capital para os desembolsos iniciais',money(f.initialShortfall)],['Pagamentos futuros previstos sem cobertura',money(r.cash.reduce((a,x)=>a+Number(x.unfunded||0),0))],['Reserva mínima projetada',money(r.parameters.N8)],['Mês da reserva mínima',r.parameters.N4],['Primeiro mês com saldo negativo',r.parameters.P5||'Nenhum'],['Quitação prevista',r.payoff||'Não quitado no horizonte'],['Reserva na quitação',money(r.parameters.N9)],['Salário necessário para parcelas',money(r.cash.reduce((s,x)=>s+(x.paymentFromSalary||0),0))],['Juros totais do financiamento',money(r.parameters.N10)],['Total do financiamento',money(r.parameters.N11)],['Custos do financiamento além do principal',money(r.parameters.H14)]])+'<p class="fine">Móveis e eletros parcelados permanecem investidos até os vencimentos. A reserva para a construtora e os demais desembolsos imediatos já estão descontados; não são retirados novamente no fluxo mensal.</p></div>'}

function referenceReserveView(reference){return '<details class="card" id="summaryReferenceReserve"><summary>Projeção de reserva da planilha — conferir mês a mês</summary>'+(reference?'<p class="fine">Referência da última planilha importada, com as regras originais. Alterações nas premissas, despesas e pagamentos do aplicativo atualizam somente o cenário atual. Reserva mínima e quitação são datas diferentes.</p>'+engineTable(['Mês','Reserva inicial','Rendimento líquido','Aporte salário','Aporte extra / PLR','Parcela','Reserva final'],reference.cash.map(x=>[x.A,...['C','E','F','G','H','I'].map(k=>money(x[k]))])):'<p>Leia a planilha do OneDrive na aba Configurações para carregar a projeção original. Nenhum valor de referência foi presumido.</p>')+'</details>'}

function cBankBalance(bank){const value=engineModel()?.bankBalances?.[bank];return Number.isFinite(value)?money(value):'Aguardando saldos do Controle Financeiro'}
